import unittest


def encode_shift(s: str):
    return "".join([chr(((ord(ch) + 5 - ord("a")) % 26) + ord("a")) for ch in s])


def decode_shift(s: str):
    return "".join([chr(((ord(ch) - 5 - ord("a")) % 26) + ord("a")) for ch in s])


class TestEncodeShift(unittest.TestCase):

    def test_basic_shift(self):
        self.assertEqual(encode_shift("abc"), "fgh")

    def test_single_character(self):
        self.assertEqual(encode_shift("a"), "f")
        self.assertEqual(encode_shift("z"), "e")

    def test_wraparound(self):
        # 'v' + 5 wraps past 'z' back to 'a'
        self.assertEqual(encode_shift("vwxyz"), "abcde")

    def test_empty_string(self):
        self.assertEqual(encode_shift(""), "")

    def test_full_alphabet(self):
        self.assertEqual(encode_shift("abcdefghijklmnopqrstuvwxyz"), "fghijklmnopqrstuvwxyzabcde")

    def test_roundtrip(self):
        for s in ["hello", "world", "python", "xyz", "aaa", "zzz"]:
            self.assertEqual(decode_shift(encode_shift(s)), s)

    def test_decode_basic(self):
        self.assertEqual(decode_shift("fgh"), "abc")

    def test_decode_wraparound(self):
        self.assertEqual(decode_shift("abcde"), "vwxyz")


if __name__ == "__main__":
    unittest.main()
